NAME='Prochitecture Streets / Crossing-to-free separator candidate v1'
FIELDS=('bundle_id','member_a','member_b','crossing_corridor','crossing_street',
        'a_attached','a_external','a_inner_side','a_crossing','a_patch',
        'b_attached','b_external','b_inner_side','b_crossing','b_patch')


def contract(g,geo,*,multiple_regions=False):
    row=geo['Declaration']
    read=lambda key:g.sample(row,g.named('st_sb_'+key),0)
    actual=lambda table,key,at:g.sample(geo[table],g.named(key),at)
    same=lambda a,b:g.compare(a,b,kind='INT')
