    for key in keys:tree.interface.new_socket(name=key,in_out='INPUT',socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Cell Size',in_out='INPUT',socket_type='NodeSocketFloat').default_value=1.
    tree.interface.new_socket(name='Grass',in_out='INPUT',socket_type='NodeSocketMaterial')
    for key in ('Geometry','Diagnostics','Boundary diagnostics','Surface diagnostics','Reference','Side A','Side B','Head','Tail'):
        tree.interface.new_socket(name=key,in_out='OUTPUT',socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Valid',in_out='OUTPUT',socket_type='NodeSocketBool')
    inp=g.node('NodeGroupInput','Original pavement and continuation declaration')
