    valid=g.all(identity_valid,edge.outputs['Valid'],fill.outputs['Valid'])
    geometry=fill.outputs['Geometry'];retained=g.named('_free_existing_face','BOOLEAN')
    for key,value,kind in (('st_cn_kind',4,'INT'),('st_cn_owner',bundle,'INT'),
                           ('_cn_face_kind',4,'INT'),('_cn_face_owner',bundle,'INT'),('_cn_face_owned',True,'BOOLEAN')):
        geometry=g.store(geometry,key,g.switch(retained,value,g.named(key,kind),kind),kind,'FACE')
    region=read('region_id') if multiple_regions else bundle
