    for field in ('st_cn_mouth','st_cn_rank'):
        geometry=g.store(geometry,field,g.switch(existing,-1,g.sample(pavement,g.named(field),own),'INT'),'INT')
    geometry=g.store(geometry,'_separator_original_vertex',g.switch(existing,-1,own,'INT'),'INT')
    index=g.node('GeometryNodeInputIndex','New separator public identity').outputs[0]
    geometry=g.store(geometry,'_bridge_key',g.switch(existing,g.xyz(5,region,index),
        g.sample(pavement,g.named('_bridge_key','FLOAT_VECTOR'),own,'FLOAT_VECTOR'),'VECTOR'),'FLOAT_VECTOR')
    status=fill.outputs['Diagnostics']
